#!/bin/sh
# SPDX-License-Identifier: Apache-2.0
#
# Start script of "@COMMAND@" from the Cringle distribution (generated by `./gradlew cringleDist`).
#
# Cringle needs a JDK 21 or newer. The script uses $JAVA_HOME/bin/java if JAVA_HOME is set and java from the PATH
# otherwise, and stops with exit code 1 and a message if that is missing or older than 21.
# Extra JVM options can be given in CRINGLE_JVM_OPTS.

# the directory of the distribution, also when this script is called through a symbolic link
app_path=$0
while [ -h "$app_path" ]; do
    ls_line=$(ls -ld -- "$app_path")
    link=${ls_line#*' -> '}
    case $link in
        /*) app_path=$link ;;
        *) app_path=$(dirname "$app_path")/$link ;;
    esac
done
APP_HOME=$(cd "$(dirname "$app_path")/.." > /dev/null 2>&1 && pwd -P) || {
    echo "@COMMAND@: cannot find the installation directory of $0" >&2
    exit 1
}

if [ -n "${JAVA_HOME:-}" ]; then
    JAVACMD=$JAVA_HOME/bin/java
else
    JAVACMD=java
fi

if ! command -v "$JAVACMD" > /dev/null 2>&1; then
    echo "@COMMAND@: no Java found ($JAVACMD). Cringle needs a JDK 21 or newer: set JAVA_HOME to it or put java on the PATH." >&2
    exit 1
fi

version_line=$("$JAVACMD" -version 2>&1 | head -n 1)
major=$(printf '%s\n' "$version_line" | sed -n 's/.*version "\([0-9][0-9]*\).*/\1/p')
full=$(printf '%s\n' "$version_line" | sed -n 's/.*version "\([^"]*\)".*/\1/p')
case $major in
    '' | *[!0-9]*)
        echo "@COMMAND@: cannot tell the Java version of $JAVACMD from: $version_line. Cringle needs a JDK 21 or newer." >&2
        exit 1
        ;;
esac
if [ "$major" -lt 21 ]; then
    echo "@COMMAND@: $JAVACMD is Java $full, but Cringle needs a JDK 21 or newer. Set JAVA_HOME to a JDK 21." >&2
    exit 1
fi

# CRINGLE_JVM_OPTS is meant to be split into words
# shellcheck disable=SC2086
exec "$JAVACMD" ${CRINGLE_JVM_OPTS:-} "-Dcringle.home=$APP_HOME" -cp "$APP_HOME/lib/*" @MAIN_CLASS@ "$@"
